-- The scraper's table definitions (from its MySQL 8.4 dump, 8 Oct 2026), used to
-- build a fake scraper database for the ingest tests. Keep in sync when the
-- scraper's schema changes.

CREATE TABLE `brands` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(150) NOT NULL,
  `sourceType` enum('shopify') NOT NULL DEFAULT 'shopify',
  `sourceUrl` varchar(512) NOT NULL,
  `verificationState` enum('unverified','verified','failed') NOT NULL DEFAULT 'unverified',
  `verificationError` varchar(1000) DEFAULT NULL,
  `verifiedAt` datetime(3) DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `syncedCount` int unsigned NOT NULL DEFAULT '0',
  `validCount` int unsigned NOT NULL DEFAULT '0',
  `queueCount` int unsigned NOT NULL DEFAULT '0',
  `awaitingFirstPublishCount` int unsigned NOT NULL DEFAULT '0',
  `liveActiveCount` int unsigned NOT NULL DEFAULT '0',
  `liveInactiveCount` int unsigned NOT NULL DEFAULT '0',
  `editedCount` int unsigned NOT NULL DEFAULT '0',
  `liveActiveOutOfStockCount` int unsigned NOT NULL DEFAULT '0',
  `removedCount` int unsigned NOT NULL DEFAULT '0',
  `countsUpdatedAt` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uqBrandSourceUrl` (`sourceUrl`),
  KEY `ixBrandVerification` (`verificationState`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `liveProducts` (
  `id` varchar(80) NOT NULL,
  `brandId` int unsigned NOT NULL,
  `productUrl` varchar(1024) NOT NULL,
  `title` varchar(255) NOT NULL,
  `description` text,
  `type` varchar(100) DEFAULT NULL,
  `tags` json NOT NULL,
  `price` decimal(12,2) NOT NULL,
  `priceMax` decimal(12,2) NOT NULL,
  `compareAtPrice` decimal(12,2) DEFAULT NULL,
  `inStock` tinyint(1) NOT NULL,
  `onSale` tinyint(1) NOT NULL,
  `sizesInStock` json NOT NULL,
  `variants` json NOT NULL,
  `images` json NOT NULL,
  `primaryImage` varchar(1024) NOT NULL,
  `imageCount` smallint unsigned NOT NULL DEFAULT '0',
  `sourcePublishedAt` datetime DEFAULT NULL,
  `sourceCreatedAt` datetime NOT NULL,
  `sourceUpdatedAt` datetime DEFAULT NULL,
  `scrapedAt` datetime(3) NOT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `contentHash` char(64) NOT NULL,
  `tagsText` text NOT NULL,
  `removedAt` datetime(3) DEFAULT NULL,
  `isActive` tinyint(1) NOT NULL DEFAULT '1',
  `isEdited` tinyint(1) NOT NULL DEFAULT '0',
  `editedBy` int unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ixLiveFeed` (`isActive`,`sourceCreatedAt`,`id`),
  KEY `ixLiveBrand` (`brandId`,`isActive`,`sourceCreatedAt`,`id`),
  KEY `ixLiveSale` (`isActive`,`onSale`,`sourceCreatedAt`,`id`),
  KEY `ixLiveRemoved` (`brandId`,`removedAt`),
  KEY `ixLiveState` (`isActive`,`removedAt`,`inStock`),
  FULLTEXT KEY `ftLiveSearch` (`title`,`type`,`tagsText`),
  CONSTRAINT `liveProducts_ibfk_1` FOREIGN KEY (`brandId`) REFERENCES `brands` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

